import { type ComponentProps, type FC, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { Accordion, AccordionItem, AccordionTrigger, AccordionContent } from "@/components/ui/accordion.js";
import { Render, type RenderProps, type RenderProp } from "./render.js";

export const AccordionOutline: FC<ComponentProps<typeof Accordion>> = ({ className, ...props }) => {
    return <Accordion className={cn("rounded-lg border", className)} {...props} />;
};

export const AccordionOutlineItem: FC<ComponentProps<typeof AccordionItem>> = ({ className, ...props }) => {
    return <AccordionItem className={cn("border-b px-4 last:border-b-0", className)} {...props} />;
};

export const AccordionOutlineTrigger: FC<ComponentProps<typeof AccordionTrigger>> = ({
    className,
    ...props
}) => {
    return <AccordionTrigger className={cn("items-center", className)} {...props} />;
};

interface AccordionCardProps
    extends
        Omit<ComponentProps<typeof AccordionOutline>, "title" | "value" | "defaultValue">,
        Partial<Pick<ComponentProps<typeof AccordionContent>, "keepMounted">> {
    /** @default true */
    collapsible?: boolean;
    title?: ReactNode;
    /**
     * Default open state
     * @default true
     */
    defaultOpen?: boolean;
    /**
     * Controlled open state
     */
    open?: boolean;
    renderTrigger?: RenderProp;
    renderContent?: RenderProp;
    triggerProps?: ComponentProps<typeof AccordionOutlineTrigger>;
}

export const AccordionCard: FC<AccordionCardProps> = ({
    children,
    collapsible = true,
    title,
    keepMounted,
    open,
    defaultOpen = true,
    renderTrigger,
    renderContent,
    triggerProps,
    ...props
}) => {
    const value = "content";
    const hasHeader = !!title || collapsible;
    const controlled = typeof open !== "undefined";

    return (
        <AccordionOutline
            defaultValue={controlled ? undefined : defaultOpen ? [value] : []}
            value={controlled ? (open ? [value] : []) : undefined}
            {...props}
        >
            <AccordionOutlineItem value={value}>
                {hasHeader &&
                    (collapsible ? (
                        <AccordionOutlineTrigger render={renderTrigger} {...triggerProps}>
                            {title}
                        </AccordionOutlineTrigger>
                    ) : (
                        <AccordionStaticHeader>
                            <Render render={renderTrigger}>
                                <AccordionTitle>{title}</AccordionTitle>
                            </Render>
                        </AccordionStaticHeader>
                    ))}
                <AccordionContent render={renderContent} keepMounted={!!keepMounted}>
                    {children}
                </AccordionContent>
            </AccordionOutlineItem>
        </AccordionOutline>
    );
};

interface AccordionTitleProps extends ComponentProps<"div"> {}

export const AccordionTitle: FC<AccordionTitleProps> = ({ className, children, ...props }) => {
    return <h3 className="text-sm font-medium">{children}</h3>;
};

interface AccordionStaticHeaderProps extends ComponentProps<"div">, RenderProps {}

export const AccordionStaticHeader: FC<AccordionStaticHeaderProps> = ({
    className,
    children,
    render,
    ...props
}) => {
    return (
        <Render render={render}>
            <div className={cn("flex flex-1 items-center justify-between py-2.5", className)} {...props}>
                {children}
            </div>
        </Render>
    );
};

interface FormCardProps extends AccordionCardProps {}

/**
 * {@link AccordionCard} variant:
 *
 * Renders the accordion card as a form fieldset with a legend as the trigger.
 * Defaults {@link AccordionCardProps.keepMounted} to true
 * and {@link AccordionCardProps.collapsible} to false for form compatibility.
 */
export const FormCard: FC<FormCardProps> = ({
    children,
    collapsible = false,
    keepMounted = true,
    ...props
}) => {
    return (
        <AccordionCard
            collapsible={collapsible}
            keepMounted={keepMounted}
            render={<fieldset />}
            renderTrigger={<legend />}
            {...props}
            triggerProps={{ nativeButton: false, className: "cursor-pointer", ...props.triggerProps }}
        >
            {children}
        </AccordionCard>
    );
};
